import re
import logging
import time
from requests.exceptions import ConnectTimeout
from functools import wraps
from taf.sbts.oam.coam.admin import admin  # type: ignore
from taf.sbts.oam.coam.admin.exceptions import IncorrectParameterValue, DataNotAvailable  # type: ignore
from ute_common_admin.exception import AdminApiProcedureFailureException  # type: ignore
from taf.ul.sc.perf.exceptions import BTSNotOnAir


def login_logout(web_fun):
    @wraps(web_fun)
    def wrapper(self, *args, **kwargs):
        self.connect()
        try:
            result = web_fun(self, *args, **kwargs)
            return result
        finally:
            self.disconnect()

    return wrapper


class COAM(object):
    """Generic keywords for eNB and gNB"""

    def __init__(self, ip, device_name='ENB0', username='Nemuadmin', password='nemuuser'):
        """

        :param ip: IP for connection to REST_API
        :param device_name: Used for Alias
        :param username: username for REST_API
        :param password: password for REST_API
        """
        self.ip = ip
        self.username = username
        self.password = password
        self.device_name = device_name

        self.admin = admin()
        self.connection = None

    def connect(self):
        """
        Connect to BTS

        :return: None
        """
        self.connection = self.admin.connect_to(bts_host=self.ip,
                                                username=self.username,
                                                password=self.password,
                                                name=self.device_name)

    def disconnect(self):
        """
        Disconnect from BTS

        :return: None
        """
        self.admin.teardown(connection=self.device_name)

    @login_logout
    def get_sw_version(self):
        """
        Get software version.

        :return: software version.
        """
        try:
            sw_version = self.admin.get_sw_version(connection=self.device_name)
        except AdminApiProcedureFailureException as e:
            sw_version = None
            logging.warning("Cannot get Software Version from BTS, {}".format(repr(e)))
        return sw_version

    @login_logout
    def get_release_version(self):
        """
        Get release version.

        :return: release version
        """
        sw_release = self.admin.get_sw_release_name(connection=self.device_name)
        return sw_release

    @login_logout
    def reset_and_wait_for_site(self, timeout=400):
        """
        Reset site and wait for OAM Node-B reconnection.

        :return: site reset status
        """
        return self.admin.reset_site(timeout=timeout, connection=self.device_name)

    @login_logout
    def perform_commissioning(self, scf_file, skip_parameter_relation_errors=False, should_activate=True,
                              timeout=600):

        return self.admin.perform_commissioning(scf_file=scf_file,
                                                skip_parameter_relation_errors=skip_parameter_relation_errors,
                                                should_activate=should_activate,
                                                timeout=timeout,
                                                connection=self.device_name)

    @login_logout
    def perform_recommissioning(self, delta, skip_parameter_relation_errors=False, should_activate=True, timeout=600):
        """
        Perform parameter recommissioning, update and delete operation can be used.

        :param list delta: list of parameters to update. Sample delta:
                delta = [{
                            'distName': dist_name,
                            'operation': 'update',
                            'parameters': [{
                                            'operation': operation,
                                            'parameterName': parameter,
                                            'value': value}]}]
                where:
                    dist_name: Object dist name ie. "MRBTS-1/LNBTS-1/LNMME-0"
                    parameter: Parameter name ie. "ipAddrPrim"
                    operation: Parameter operation (update or delete)
                    value: Parameter value ie. "10.0.1.99" or [{"eea1":0, "eea0":1, "eea3":8, "eea2":0}]
        :param boolean skip_parameter_relation_errors: Skip parameter relation errors
        :param bool should_activate: Should automatically activate plan
        :param Union[int,str] timeout: Time to wait for positive procedure result
        :raises ute_common_admin.exception.AdminApiProcedureFailureException: Will be raised if
            recommissioning fails
        :return dict: Recommissioning status
        """

        parameters = {"planObjects": delta, "shouldBeActivated": should_activate}
        if skip_parameter_relation_errors:
            parameters["skipParameterRelationErrors"] = True
        status = self.connection._api_client.execute_procedure("recommission", parameters, timeout)
        if status is None:
            raise DataNotAvailable("Recommissioning status has not been provided by M-Plane.")
        return status

    @login_logout
    def collect_snapshot(self, snapshot_path, timeout=900):
        self.admin.get_snapshot(target_file_name=snapshot_path, timeout=timeout, connection=self.device_name)

    @login_logout
    def get_current_scf_file(self, local_dir_path, file_name, timeout=60):
        self.admin.get_current_scf_file(local_dir_path=local_dir_path,
                                        file_name=file_name, timeout=timeout, connection=self.device_name)

    @login_logout
    def software_update(self, sw_package, timeout=1800):
        """
        Perform eNB software update.

        :param sw_package: full path to build file
        :param timeout: time in seconds, after timeout expires an exception is raised
        :return: software update status
        """
        return self.admin.update_software(sw_package=sw_package, timeout=timeout, connection=self.device_name)

    @login_logout
    def get_active_alarms(self, timeout=60):
        """
        Get a list of active alarms from eNB.

        :param timeout: time in seconds, after timeout expires an exception is raised
        :return: alarm list
        """
        return self.admin.get_active_alarms(timeout=timeout, connection=self.device_name)

    @login_logout
    def get_active_alarms_number(self, timeout=60):
        """
        Get a number of active alarms from eNB.

        :param timeout: time in seconds, after timeout expires an exception is raised
        :return: number of active alarms
        """
        return self.admin.get_active_alarms_number(timeout=timeout, connection=self.device_name)

    def wait_for_onair(self, mode='all_cells', timeout=930, interval=30, raise_error=True, allow_degraded_status=False):
        """
        Wait until BTS gets on air or timeout expire.

        :param mode: all_cells or bts
        :param timeout: time in seconds, after timeout expires an exception is raised
        :param interval: time between checks of operationalState
        :param raise_error: True if moler error should be raised when gNB is not onAir, False otherwise
        :param allow_degraded_status: If True --> availabilityStatus could be 'Degraded' to mark cell as onAir
        :return: None
        """
        on_air_params = {}
        if mode == 'all_cells':
            check_if_onair = self.check_if_all_cells_are_onair
            on_air_params = {'allow_degraded_status': allow_degraded_status}
        else:
            check_if_onair = self.check_if_bts_is_onair

        start_time = time.time()

        logging.info("Checking if BTS is onAir...")
        while time.time() - start_time <= timeout:
            if check_if_onair(**on_air_params):
                logging.info("BTS is onAir")
                return True
            else:
                time.sleep(interval)

        if raise_error:
            raise BTSNotOnAir("BTS is not on air after {} seconds".format(timeout))

        return False

    def check_if_bts_is_onair(self):
        """
        Check if BTS operationalStatus is onAir.

        :return: True if gNB is onAir, False otherwise
        """
        try:
            operational_state = self._get_operational_state()
            return re.match(r'onAir', operational_state, re.I)
        except ConnectTimeout as e:
            logging.warning('There is an requests exception in check_if_bts_is_onair: {}'.format(repr(e)))

    @login_logout
    def _get_operational_state(self):
        """
        Returns current proceduralState of managed object from NIDD by given distName.

        :return: operationalState value as string
        """
        status_dict = self.admin.get_bts_statuses(timeout=120, connection=self.device_name)
        return status_dict['proceduralState']

    def check_if_all_cells_are_onair(self, allow_degraded_status=False):
        all_cells_status = []

        try:
            cells_info = self._get_cells_info()
        except DataNotAvailable:
            logging.warning("Cannot get cell info")
            return False

        for cell_type in cells_info['cells']:
            for cell_info in cells_info['cells'][cell_type]:
                if cell_info:
                    status = self._check_if_cell_is_onair(cell_info, allow_degraded_status=allow_degraded_status)
                    all_cells_status.append(status)

        return all(all_cells_status) if all_cells_status else False

    @login_logout
    def _get_cells_info(self):
        cells_info = self.connection._api_client.execute_customer_procedure("getCellList", {}, timeout=120)

        if cells_info is None:
            raise DataNotAvailable("Cell data has not been provided by M-Plane.")

        return cells_info.get('requestMessage', cells_info)

    def _check_if_cell_is_onair(self, cell_info, allow_degraded_status=False):
        expected_statuses = {
            "availabilityStatus": ["online"],
            "operationalState": ["enabled"],
            "administrativeState": ["unlocked"],
        }

        if allow_degraded_status:
            expected_statuses["availabilityStatus"].append('degraded')

        try:
            logging.info("Checking status of {}".format(cell_info['cellName']))
            status = self._verify_cell_statuses(expected_statuses, cell_info['status'])
            if status:
                logging.info("{} is onAir".format(cell_info['cellName']))
                return True
        except IncorrectParameterValue:
            logging.info("{} is not onAir".format(cell_info['cellName']))
        except KeyError:
            logging.debug("Cannot check status of {}. Data not available".format(cell_info['cellName']))

        return False

    @staticmethod
    def _verify_cell_statuses(expected_statuses, cell_status):
        """
        Verify nb cell statuses are as expected.
        Unify keys and status values to CNI-61110 changes.

        :param expected_statuses: dict with expected statuses.
        :return: None. Raise error.
        """
        for status in expected_statuses:
            if status not in cell_status.keys():
                if status == 'availabilityStatus':
                    cell_status[status] = 'online'
                else:
                    cell_status[status] = None

        try:
            COAM.check_if_cell_status_is_expected(cell_status, expected_statuses)
        except KeyError as e:
            raise DataNotAvailable("Cannot get expected status info: {}".format(repr(e)))
        return True

    @staticmethod
    def check_if_cell_status_is_expected(cell_status, expected_statuses):
        for status in expected_statuses:
            if cell_status[status].lower() not in expected_statuses[status]:
                logging.debug("Expected statuses: {}".format(expected_statuses))
                logging.debug("Received statuses: {}".format(cell_status))
                raise IncorrectParameterValue(
                    "Expected status: {}, but received status is: {}".format(expected_statuses[status],
                                                                             cell_status[status]))
